namespace Portfolio.ApiBase.Configuration;

/// <summary>
/// Extension methods for registering CORS policies directly into the IServiceCollection.
/// Provides an alternative to the <see cref="Builders.AppBuilder{TBuilder}.ConfigureCors"/> approach for manual pipeline setup.
/// </summary>
public static class CorsPolicyExtensions
{
    /// <summary>
    /// Registers the CORS policy generated by <see cref="CorsPolicyConfigurator"/> into the DI container.
    /// </summary>
    public static IServiceCollection AddCorsPolicy(
        this IServiceCollection services,
        IConfiguration configuration,
        ILogger logger,
        Action<CorsPolicyBuilder>? configure = null)
    {
        var policy = CorsPolicyConfigurator.Configure(configuration, logger, configure);
        
        services.AddSingleton(policy);
        services.AddCors(options => options.AddDefaultPolicy(policy));

        return services;
    }
}